/** Read-only editorial judgements. Quotes always come from supplied evidence. */
import { choice, noul, type ChoiceQuestion, type SystemOneQuestion } from "./system-one";

export type WritingLensId = "reader" | "revision" | "voice" | "promises" | "scraps" | "room" | "circling" | "research";
export interface WritingLensInput {
  draft: string;
  previousDraft?: string;
  audience?: string;
  voiceSamples?: Array<{ id: string; text: string }>;
  scraps?: Array<{ id: string; text: string }>;
  notes?: Array<{ id: string; text: string; author?: string }>;
  /** Chronological, oldest first. The current draft is appended if different. */
  revisions?: Array<{ id: string; text: string }>;
  sources?: Array<{ id: string; claim: string; source: string; previousClaim?: string }>;
  intentionalPromises?: string[];
  focus?: string;
}
export interface WritingLensFinding {
  id: string;
  title: string;
  detail: string;
  passage?: string;
  relatedPassage?: string;
  needsReview?: boolean;
  kind?: string;
}
export interface WritingLensResult {
  status: "complete" | "unavailable" | "missing-input";
  findings: WritingLensFinding[];
  coverage: string;
  notice?: string;
}
export interface WritingLensCaller {
  (input: { state: Record<string, unknown>; questions: Record<string, SystemOneQuestion> }): Promise<{
    ok: boolean;
    answers?: Record<string, unknown>;
    error?: string;
  }>;
}

export const WRITING_LENSES: Array<{ id: WritingLensId; label: string; description: string }> = [
  { id: "reader", label: "Read without the ending", description: "See where a reader may need context they have not reached yet." },
  { id: "revision", label: "What did the edit cost?", description: "Compare clarity, specificity, feeling, caution, and voice." },
  { id: "voice", label: "Protect your voice", description: "Compare an edit with passages you chose to preserve." },
  { id: "promises", label: "Promises to the reader", description: "Connect setups and questions to possible payoffs." },
  { id: "scraps", label: "Give scraps another life", description: "Find a place for writing you explicitly saved." },
  { id: "room", label: "Make disagreement useful", description: "Separate repeated advice from real editorial choices." },
  { id: "circling", label: "Are these edits moving?", description: "Compare recent revisions for progress or equivalent alternatives." },
  { id: "research", label: "Check research drift", description: "Recheck a claim against the source passage you supplied." },
