  if (!record(value) || value.type !== "choice" || typeof value.choice !== "string" || !q.criteria.includes(value.choice) || !probability(value.confidence) || !record(value.probabilities)) return;
  const distribution = value.probabilities;
  if (Object.keys(distribution).length !== q.criteria.length || !q.criteria.every((option) => probability(distribution[option]))) return;
  const probabilities = q.criteria.map((option) => distribution[option] as number);
  if (Math.abs(probabilities.reduce((a, b) => a + b, 0) - 1) > 0.02) return;
  const selected = distribution[value.choice] as number;
  if (selected + 0.0001 < Math.max(...probabilities)) return;
