    const evidence = paragraphs.map((text, index) => ({ id: `passage-${index}`, text }));
    const checks: Record<string, Check> = {};
    candidates.forEach((candidate, i) => {
      if (input.intentionalPromises?.includes(candidate.id)) return;
      const options = evidence.filter((_, j) => j !== i).map((p) => p.id);
      // Candidate selection and speculative payoff selection are independent.
      const promiseQuestion = noul(SAFETY + `Does \`candidates[${i}].text\` create a concrete reader expectation (a setup, explicit question, or promised explanation) that another passage could fulfil? Mere statements do not count.`);
      const payoffQuestion = choice(SAFETY + `Assuming \`candidates[${i}].text\` makes a reader promise, select the strongest passage in \`evidence\` that fulfils it. Do not select mere topic overlap. Choose no relevant match if the supplied excerpts contain no payoff.`, [...options, NO_MATCH, INSUFFICIENT]);
      let presence: number | undefined;
      checks[`promise${i}`] = { question: promiseQuestion, read(value) {
        if (!record(value) || value.type !== "noul" || !probability(value.noul)) return undefined;
        presence = value.noul;
        return null;
      } };
      checks[`payoff${i}`] = { question: payoffQuestion, read(value) {
        if (presence !== undefined && presence < 0.35) return null;
        const answer = readChoice(value, payoffQuestion);
        if (!answer || presence === undefined) return undefined;
        const payoff = evidence.find((p) => p.id === answer.value);
        const review = presence < 0.7 || answer.review || !payoff && limits.size > 0;
        return { id: candidate.id, title: review ? "Review this possible promise" : payoff ? "A possible payoff is present" : "No payoff found in reviewed text", detail: review ? "The promise or its resolution is uncertain. You can mark this as intentionally unresolved." : payoff ? "Compare the setup and the selected passage to decide whether the expectation is met." : "Check whether this expectation should be fulfilled or intentionally left open.", passage: candidate.text, relatedPassage: payoff?.text, needsReview: review, kind: "promise" };
      } };
    });
    jobs.push({ state: { candidates, evidence }, checks });
    scope = `${candidates.filter((c) => !input.intentionalPromises?.includes(c.id)).length} candidate paragraphs checked against ${evidence.length} supplied paragraphs; intentional open promises excluded.`;
  } else if (id === "scraps") {
    const scraps = take((input.scraps || []).filter((s) => s.text.trim()), "Scraps").map((s) => ({ id: s.id, text: clip(s.text, MAX_PASSAGE, "Scrap") }));
    const focus = clip(input.focus || draft, 8_000, "Target passage");
    if (!focus.trim() || !scraps.length) return missing("Save a scrap and add a draft or target passage to find a place for it.");
    const checks: Record<string, Check> = {};
    scraps.forEach((scrap, i) => { checks[`scrap${i}`] = check({ id: `scrap-${scrap.id}`, passage: scrap.text, relatedPassage: focus, kind: "scrap" },
      `Would saved \`scraps[${i}].text\` usefully contribute to \`target\`? Select its strongest concrete role. Shared vocabulary alone is not useful relevance.`,
      ["Possible missing example", "Possible transition", "Possible counterargument", "Possible supporting detail", NO_MATCH, INSUFFICIENT]); });
    jobs.push({ state: { scraps, target: focus }, checks });
    scope = `${scraps.length} explicitly saved scraps compared with the target passage.`;
  } else if (id === "room") {
    const notes = take((input.notes || []).filter((n) => n.text.trim()), "Editor notes").map((n) => ({ ...n, text: clip(n.text, 1_000, "Editor note") }));
    if (notes.length < 2) return missing("Collect at least two editor notes to compare their advice.");
    const checks: Record<string, Check> = {};
    notes.forEach((a, i) => notes.slice(i + 1).forEach((b, offset) => {
      const j = i + offset + 1;
      checks[`pair${i}_${j}`] = check({ id: `room-${a.id}-${b.id}`, passage: a.text, relatedPassage: b.text, kind: "room" },
        `Compare editorial advice in \`notes[${i}]\` and \`notes[${j}]\` using \`draft\`. Duplicates recommend substantially the same change. Compatible suggestions can both be followed. A conflict requires a writer's choice because following one undermines the other. Unrelated notes have no relevant match.`,
        ["Repeated advice", "Compatible suggestions", "An editorial choice is needed", NO_MATCH, INSUFFICIENT]);
    }));
    jobs.push({ state: { notes, draft }, checks });
    scope = `${Object.keys(checks).length} note pairs from ${notes.length} notes; the quoted notes show the competing advice.`;
  } else if (id === "circling") {
    const history = (input.revisions || []).filter((r) => r.text.trim());
    if (draft.trim() && history.at(-1)?.text !== input.draft) history.push({ id: "current", text: input.draft });
    if (history.length < 3) return missing("Keep at least three chronological draft snapshots to compare revision direction.");
    const revisions = history.slice(-4).map((r) => ({ id: r.id, text: clip(r.text, 6_000, "Revision snapshot") }));
    if (history.length > 4) limits.add(`Latest 4 of ${history.length} snapshots`);
    jobs.push({ state: { revisions }, checks: { direction: check({ id: "circling", passage: revisions.at(-1)!.text, relatedPassage: revisions[0].text, kind: "circling" },
      "Compare `revisions`, ordered oldest to newest. Is the text alternating between substantially equivalent phrasings, exploring meaningfully different approaches, or making directional substantive progress? Describe document changes only, never the writer's psychology. Use no relevant match when snapshots do not show a revision pattern.",
      ["Equivalent alternatives recur", "Meaningfully different approaches", "Substantive progress", NO_MATCH, INSUFFICIENT],
      { "Equivalent alternatives recur": "Consider keeping both versions and returning later. Equivalent wording can still be a deliberate choice.", "Meaningfully different approaches": "These snapshots appear to explore different ways of making the piece work.", "Substantive progress": "The sequence appears to make substantive changes in a consistent direction." }) } });
    scope = `${revisions.length} chronological snapshots compared; this describes the text, not your state of mind.`;
  } else if (id === "research") {
    const sources = take((input.sources || []).filter((s) => s.claim.trim() && s.source.trim()), "Claim/source pairs");
    if (!sources.length) return missing("Save a current claim and the source passage it relies on.");
    sources.forEach((source) => {
      const claim = clip(source.claim, MAX_PASSAGE, "Claim");
      const evidence = clip(source.source, 8_000, "Source excerpt");
      const previousClaim = clip(source.previousClaim || "", MAX_PASSAGE, "Previous claim");
      const checks: Record<string, Check> = { support: check({ id: `research-${source.id}`, passage: claim, relatedPassage: evidence, kind: "research" },
        "Does `source` support `currentClaim` as worded, including quantities, scope, causal claims and qualifications? Judge only the supplied source, not external knowledge. This is a support check, not verification that the source itself is true.",
        ["Supported by supplied passage", "Claim exceeds supplied evidence", "Source contradicts claim", "Source does not address claim", INSUFFICIENT],
        { "Supported by supplied passage": "The supplied excerpt appears to support this wording. The source's own accuracy has not been verified.", "Claim exceeds supplied evidence": "Compare the claim's scope and qualifications with the source before relying on this citation.", "Source contradicts claim": "The supplied source appears to conflict with this wording; review both passages.", "Source does not address claim": "This excerpt does not appear to provide evidence for the claim." }) };
      if (previousClaim) checks.drift = check({ id: `drift-${source.id}`, passage: claim, relatedPassage: previousClaim, kind: "research" },
        "Compare `previousClaim` and `currentClaim` against `source`. Did the revision change how much source support is available for the exact claim?", ["Revision weakens source support", "Revision improves source support", "Source support is similar", INSUFFICIENT]);
      jobs.push({ state: { currentClaim: claim, source: evidence, previousClaim }, checks });
    });
    scope = `${sources.length} explicit claim/source pairs checked. Supplied excerpts only; source accuracy and other claims are not verified.`;
  }

  const findings: WritingLensFinding[] = [];
  let valid = 0;
  let failed = 0;
  for (const job of jobs) {
    const entries = Object.entries(job.checks);
    if (!entries.length) continue;
    let answers: Record<string, unknown> | undefined;
    try {
      const result = await call({ state: job.state, questions: Object.fromEntries(entries.map(([key, c]) => [key, c.question])) });
      if (result.ok && record(result.answers)) answers = result.answers;
    } catch { /* A transport failure must not invent a judgement. */ }
    for (const [key, c] of entries) {
      const finding = answers ? c.read(answers[key]) : undefined;
      if (finding === undefined) failed++;
      else { valid++; if (finding) findings.push(finding); }
    }
  }
  const notice = [limits.size ? `Partial coverage: ${Array.from(limits).join("; ")}.` : "", failed ? `${failed} judgements could not be read or completed. Try again to review those items.` : "", findings.some((f) => f.needsReview) ? "Uncertain judgements need your review; these tools do not change the draft." : ""].filter(Boolean).join(" ");
  return { status: failed && !valid ? "unavailable" : "complete", findings, coverage: scope, ...(notice ? { notice } : {}) };
}

